import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const CHANNELS = ['포털', '메신저', '모바일', '대화방', '메일'];

function requireText(value: unknown, label: string, max: number): string {
  if (typeof value !== 'string' || value.trim() === '' || value.length > max) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값을 확인해 주세요.');
  }
  return value;
}

function requireInteger(value: unknown, label: string): number {
  if (typeof value !== 'number' || !Number.isInteger(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + ' 값은 정수여야 합니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr03606Controller {
  @Post('/notifications')
  @HttpCode(200)
  async createNotification(@Req() req: Request) {
    // 권한: 로그인 사용자 (별도 역할 제한 없음)
    const user = currentUser(req);
    const data = checks.inputOf(req.body);
    const recipientId = requireInteger(data['recipientId'], '수신자');
    const title = requireText(data['title'], '알림 제목', 200);
    const eventType = requireText(data['eventType'], '알림 이벤트 유형', 50);
    const targetType = requireText(data['targetType'], '바로가기 대상 유형', 50);
    const targetId = requireInteger(data['targetId'], '바로가기 대상 ID');
    const channel = requireText(data['channel'], '알림 채널', 10);
    if (!CHANNELS.includes(channel)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '알림 채널 값을 확인해 주세요.');
    }
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id AS "employeeId" FROM employee WHERE employee_id = CAST(:recipientId AS bigint)',
        { recipientId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '알림 대상자를 찾을 수 없습니다.');
      }
      const rows = await db.query(
        'INSERT INTO notification (recipient_id, channel, title, read_status, event_type, target_type, target_id, created_at, updated_at) ' +
          'VALUES (CAST(:recipientId AS bigint), :channel, :title, :readStatus, :eventType, :targetType, CAST(:targetId AS bigint), now(), now()) ' +
          'RETURNING notification_id AS "notificationId"',
        {
          recipientId,
          channel,
          title,
          readStatus: '안읽음',
          eventType,
          targetType,
          targetId,
        },
      );
      return rows[0];
    });
  }
}

