import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, NumberInput, Select, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

const CHANNEL_OPTIONS: [string, string][] = [
  ['포털', '포털'],
  ['메신저', '메신저'],
  ['모바일', '모바일'],
  ['대화방', '대화방'],
  ['메일', '메일'],
];

export default function FnSfr03606Page({ role, notify }: PageProps) {
  const [rows, setRows] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [recipientId, setRecipientId] = useState<number | string>('');
  const [title, setTitle] = useState('');
  const [eventType, setEventType] = useState('');
  const [targetType, setTargetType] = useState('');
  const [targetId, setTargetId] = useState<number | string>('');
  const [channel, setChannel] = useState('');

  function openCreate() {
    setRecipientId('');
    setTitle('');
    setEventType('');
    setTargetType('');
    setTargetId('');
    setChannel('');
    setCreating(true);
  }

  async function submit() {
    if (recipientId === '' || title.trim() === '' || eventType.trim() === '' || targetType.trim() === '' || targetId === '' || channel === '') {
      throw new Error('모든 항목을 입력해 주세요.');
    }
    const res = await call('POST', '/notifications', role, {
      recipientId,
      title,
      eventType,
      targetType,
      targetId,
      channel,
    });
    setRows([
      { notificationId: res['notificationId'], title, recipientId, channel, readStatus: '안읽음' },
      ...rows,
    ]);
    setCreating(false);
    notify('알림을 생성했습니다.');
  }

  async function markRead(row: Row) {
    try {
      const res = await call('POST', '/notifications/' + String(row['notificationId']) + '/read', role, {});
      setRows(rows.map((r) => (r['notificationId'] === row['notificationId'] ? { ...r, readStatus: res['readStatus'] } : r)));
      notify('알림을 읽음 처리했습니다.');
    } catch (e) {
      notify(e instanceof Error ? e.message : '읽음 처리에 실패했습니다.');
    }
  }

  return (
    <div className="doc">
      <section className="box">
        <h2>그룹웨어 이벤트 알림</h2>
        <Band total={rows.length}>
          <button onClick={openCreate}>알림 생성</button>
        </Band>
        <DataTable
          rows={rows}
          empty="아직 생성한 알림이 없습니다. 알림 생성 버튼을 눌러 시작하세요."
          columns={[
            { key: 'title', label: '알림 제목' },
            { key: 'recipientId', label: '수신자', render: (r) => <RefNameCell role={role} value={r['recipientId']} /> },
            { key: 'channel', label: '알림 채널' },
            { key: 'readStatus', label: '읽음 상태', render: (r) => <Badge value={r['readStatus']} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) =>
                r['readStatus'] === '안읽음' ? (
                  <button className="ghost" onClick={() => markRead(r)}>읽음 처리</button>
                ) : null,
            },
          ]}
        />
      </section>
      {creating && (
        <Drawer title="알림 생성" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="생성">
            <Field label="수신자" required>
              <LookupSelect table="employee" role={role} value={recipientId} onChange={setRecipientId} />
            </Field>
            <Field label="알림 제목" required>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label="알림 이벤트 유형" required>
              <TextInput value={eventType} onChange={setEventType} />
            </Field>
            <Field label="바로가기 대상 유형" required>
              <TextInput value={targetType} onChange={setTargetType} />
            </Field>
            <Field label="바로가기 대상 ID" required>
              <NumberInput value={targetId} onChange={setTargetId} />
            </Field>
            <Field label="알림 채널" required>
              <Select value={channel} onChange={setChannel} options={CHANNEL_OPTIONS} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}

function RefNameCell({ role, value }: { role: string; value: unknown }) {
  return <RefName table="employee" role={role} value={value} />;
}
